  if(bytes.length!==before.size||after.size!==before.size||after.mtimeMs!==before.mtimeMs||after.ctimeMs!==before.ctimeMs)
   throw fail('OPENAPI_OPERATION_POLICY_FILE_CHANGED','The original file changed during receiving.');
