   ...(file||expectedFileSha256?{expectedFileSha256:file?.sha256??expectedFileSha256}:{}),
   ...(file&&kind==='policy'?{policySha256:file.policySha256}:{}),
   ...(file?.reviewSha256?{expectedReviewSha256:file.reviewSha256}:{})};
