  if(reply.workspace!==workspace||file&&operationPolicyCanonical(file)!==operationPolicyCanonical(info))
   throw fail('OPENAPI_OPERATION_POLICY_REPLY_INVALID','The selected complete file changed between chunks.');
  file??=info;
